import { CtaBand } from "@/components/marketing/sections";
import { TOOLS, toolsByCategory, type Tool, type ToolCategory } from "@/lib/tools/catalog";
import {
  IconGlobe,
  IconNetwork,
  IconServer,
  IconLock,
  IconCode,
  IconGauge,
  IconShield,
  IconTerminal,
  IconSpark,
  IconArrow,
} from "@/components/marketing/icons";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export const metadata: Metadata = {
  title: "Free Networking & Developer Tools",
  description:
    "A free suite of networking and developer tools: WHOIS, DNS lookup, port checker, SSL checker, HTTP headers, IP lookup, password & hash generators, subnet calculator, Base64, JSON formatter and UUID generator. No signup, no limits.",
  alternates: { canonical: "/tools" },
  openGraph: {
    title: "Free Networking & Developer Tools — Nxeon",
    description:
      "WHOIS, DNS, port & SSL checkers, HTTP headers, IP lookup, password/hash generators, subnet calculator, Base64, JSON formatter and more — free, in your browser.",
    url: "/tools",
    type: "website",
  },
};

const ICONS: Record<string, (p: { size?: number }) => React.ReactNode> = {
  globe: IconGlobe,
  network: IconNetwork,
  server: IconServer,
  lock: IconLock,
  code: IconCode,
  gauge: IconGauge,
  shield: IconShield,
  terminal: IconTerminal,
  spark: IconSpark,
};

const CATEGORY_BLURB: Record<ToolCategory, string> = {
  Network: "Diagnose domains, DNS, ports and certificates — the checks you run before and after every deploy.",
  Developer: "Everyday encode/format/generate utilities that run entirely in your browser.",
  Security: "Generate strong secrets and hashes locally — nothing is ever sent to a server.",
};

function ToolCard({ tool, delay }: { tool: Tool; delay: number }) {
  const Icon = ICONS[tool.icon] ?? IconServer;
  return (
    <Reveal delay={delay} className="h-full">
      <Link
        href={`/tools/${tool.slug}`}
        className="card card-hover group flex h-full flex-col"
      >
        <div className="mb-4 inline-flex w-fit rounded-xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 p-3 text-brand-300 transition-transform duration-200 group-hover:scale-105">
          {Icon({ size: 22 })}
        </div>
        <h3 className="flex items-center gap-1.5 text-base font-semibold text-white">
          {tool.name}
          {!tool.serverSide && (
            <span className="rounded-full border border-emerald-500/25 bg-emerald-500/10 px-1.5 py-0.5 text-[10px] font-semibold text-emerald-300">
              In-browser
            </span>
          )}
        </h3>
        <p className="mt-2 flex-1 text-sm leading-relaxed text-slate-400">{tool.tagline}</p>
        <span className="mt-4 inline-flex items-center gap-1 text-sm font-medium text-brand-300 transition-colors group-hover:text-brand-200">
          Open tool <IconArrow size={14} />
        </span>
      </Link>
    </Reveal>
  );
}

export default function ToolsHubPage() {
  const grouped = toolsByCategory();
  const order: ToolCategory[] = ["Network", "Developer", "Security"];

  const itemList = {
    "@context": "https://schema.org",
    "@type": "ItemList",
    name: "Free networking and developer tools",
    itemListElement: TOOLS.map((t, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: t.name,
      url: `${APP_URL}/tools/${t.slug}`,
    })),
  };

  return (
    <>
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(itemList) }} />

      <PageHero
        eyebrow="Free tools"
        title="Networking & developer tools,"
        highlight="free forever"
        sub={`A growing suite of ${TOOLS.length} genuinely useful utilities — WHOIS, DNS, port & SSL checks, HTTP headers, password and hash generators, subnet math and more. No signup, no limits, no tracking.`}
        primary={{ label: "Deploy a VPS", href: "/vps" }}
        secondary={{ label: "See pricing", href: "/pricing" }}
      />

      <Section tone="panel" size="sm">
        <div className="grid gap-8 text-center sm:grid-cols-3">
          <div>
            <p className="text-3xl font-bold text-white">{TOOLS.length}</p>
            <p className="mt-1 text-sm text-slate-400">Free tools</p>
          </div>
          <div>
            <p className="text-3xl font-bold text-white">$0</p>
            <p className="mt-1 text-sm text-slate-400">Forever — no account needed</p>
          </div>
          <div>
            <p className="text-3xl font-bold text-white">6</p>
            <p className="mt-1 text-sm text-slate-400">Run 100% in your browser</p>
          </div>
        </div>
      </Section>

      {order.map((cat, ci) => (
        <Section key={cat} size="lg" tone={ci % 2 === 1 ? "panel" : "base"}>
          <SectionTitle eyebrow={`${cat} tools`} title={`${cat} tools`} sub={CATEGORY_BLURB[cat]} align="left" />
          <div className="mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
            {grouped[cat].map((t, i) => (
              <ToolCard key={t.slug} tool={t} delay={(i % 3) * 60} />
            ))}
          </div>
        </Section>
      ))}

      <Section tone="deep" size="lg">
        <CtaBand />
      </Section>
    </>
  );
}

