// Thin Anthropic Messages API wrapper for the "Build with Claude AI" feature.
// No SDK / no new deps — plain fetch. BYOK: each request is made with the
// OWNER'S effective key (their stored key, else the optional platform key).

import { decryptSecret } from "./crypto-box";

const ANTHROPIC_URL = "https://api.anthropic.com/v1/messages";
const MODEL = "claude-opus-4-8";

export type ClaudeMessage = { role: "user" | "assistant"; content: string };

/** True when an optional platform-wide fallback key is configured. */
export function platformKeyConfigured(): boolean {
  return Boolean(process.env.ANTHROPIC_API_KEY && process.env.ANTHROPIC_API_KEY.trim());
}

/** Deprecated alias kept for backwards compatibility. */
export function anthropicConfigured(): boolean {
  return platformKeyConfigured();
}

/**
 * Resolve the effective key for a user: their own decrypted BYOK key if present,
 * otherwise the optional platform-wide ANTHROPIC_API_KEY. Returns null if neither
 * is available. Never throws on a bad/absent stored key (decryptSecret returns null).
 */
export function effectiveKeyFor(
  user: { anthropicKeyEnc?: string | null } | null | undefined
): string | null {
  const own = decryptSecret(user?.anthropicKeyEnc ?? null);
  if (own && own.trim()) return own.trim();
  const platform = process.env.ANTHROPIC_API_KEY;
  return platform && platform.trim() ? platform.trim() : null;
}

/**
 * Send a chat turn to Claude and return the concatenated text of the reply.
 * The caller supplies the API key (the build owner's effective key).
 * Throws when the key is missing or the API returns a non-2xx response.
 */
export async function askClaude(
  apiKey: string,
  messages: ClaudeMessage[],
  system: string,
  opts: { maxTokens?: number; timeoutMs?: number } = {}
): Promise<string> {
  if (!apiKey) throw new Error("No Anthropic API key available");

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), opts.timeoutMs ?? 60_000);
  let res: Response;
  try {
    res = await fetch(ANTHROPIC_URL, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-api-key": apiKey,
        "anthropic-version": "2023-06-01",
      },
      body: JSON.stringify({
        model: MODEL,
        max_tokens: opts.maxTokens ?? 1024,
        system,
        messages,
      }),
      signal: controller.signal,
    });
  } finally {
    clearTimeout(timer);
  }

  if (!res.ok) {
    const body = await res.text().catch(() => "");
    throw new Error(`Anthropic API ${res.status}: ${body.slice(0, 500)}`);
  }

  const data = (await res.json()) as { content?: Array<{ type: string; text?: string }> };
  const text = (data.content ?? [])
    .filter((b) => b.type === "text" && typeof b.text === "string")
    .map((b) => b.text as string)
    .join("")
    .trim();
  return text;
}

/**
 * name.com API v4 client (reseller). Auth: HTTP Basic (username:token).
 * Production: https://api.name.com  ·  Dev/sandbox: https://api.dev.name.com
 */

import { SANDBOX } from "./sandbox";

export function registrarConfigured(): boolean {
  return !!(process.env.NAMECOM_USERNAME && process.env.NAMECOM_TOKEN);
}

/**
 * Inbound transfers additionally work in SANDBOX (staging) with synthetic
 * results, so the whole transfer-in flow — quote, submit, poll, cancel — can be
 * exercised end to end without touching the registrar or a real domain.
 */
export function transfersAvailable(): boolean {
  return SANDBOX || registrarConfigured();
}

function baseUrl(): string {
  return process.env.NAMECOM_ENV === "dev" ? "https://api.dev.name.com" : "https://api.name.com";
}

function authHeader(): string {
  const raw = `${process.env.NAMECOM_USERNAME}:${process.env.NAMECOM_TOKEN}`;
  return "Basic " + Buffer.from(raw).toString("base64");
}

async function nc(
  method: string,
  path: string,
  body?: unknown,
  opts?: { nullOn404?: boolean }
): Promise<any> {
  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
  const res = await fetch(`${baseUrl()}${path}`, {
    method,
    headers: { Authorization: authHeader(), "Content-Type": "application/json" },
    body: body ? JSON.stringify(body) : undefined,
    signal: AbortSignal.timeout(30_000),
  });
  const text = await res.text();
  let json: any = {};
  try {
    json = text ? JSON.parse(text) : {};
  } catch {
    /* non-JSON error body */
  }
  if (!res.ok) {
    // Some callers treat "absent" as a normal answer (e.g. polling a transfer
    // that has already dropped off the registrar's list) — let them opt in to a
    // null instead of an exception rather than string-matching an error message.
    if (opts?.nullOn404 && res.status === 404) return null;
    const msg = json?.message || json?.details || text || `HTTP ${res.status}`;
    throw new Error(`name.com: ${msg}`);
  }
  return json;
}

const dollarsToCents = (d: number | undefined) => (d === undefined ? null : Math.round(d * 100));

/** Platform markup added to the registrar cost, as a percentage (admin-tunable via env). */
export function domainMarkupPct(): number {
  return Number(process.env.DOMAIN_MARKUP_PCT ?? 25);
}

/** Retail (customer) price for a given registrar cost, markup applied. */
export function retailCents(costCents: number | null): number | null {
  if (costCents === null) return null;
  return Math.round(costCents * (1 + domainMarkupPct() / 100));
}

export type DomainCheck = {
  domain: string;
  available: boolean;
  premium: boolean;
  priceCents: number | null; // RETAIL — what the customer pays (per year)
  costCents: number | null; // registrar cost (per year)
  renewCents: number | null; // RETAIL renewal price
};

export async function checkDomains(domains: string[]): Promise<DomainCheck[]> {
  const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: domains });
  return (json.results ?? []).map((r: any) => {
    const cost = dollarsToCents(r.purchasePrice);
    const renewCost = dollarsToCents(r.renewalPrice ?? r.purchasePrice);
    return {
      domain: r.domainName,
      available: r.purchasable === true,
      premium: r.premium === true,
      priceCents: retailCents(cost),
      costCents: cost,
      renewCents: retailCents(renewCost),
    };
  });
}

export type RegistrantContact = {
  firstName: string;
  lastName: string;
  address1: string;
  city: string;
  stateProvince: string;
  postalCode: string;
  country: string; // ISO-2
  phone: string; // +NN.NNNNNNNNNN
  email: string;
};

function ncContact(c: RegistrantContact) {
  return {
    firstName: c.firstName,
    lastName: c.lastName,
    address1: c.address1,
    city: c.city,
    state: c.stateProvince,
    zip: c.postalCode,
    country: c.country,
    phone: c.phone,
    email: c.email,
  };
}

/** Registers for `years` at the given expected price (from checkDomains). */
export async function registerDomain(
  domain: string,
  years: number,
  contact: RegistrantContact,
  purchaseCents: number
): Promise<{ expiresAt?: Date }> {
  const c = ncContact(contact);
  const json = await nc("POST", "/v4/domains", {
    domain: {
      domainName: domain,
      contacts: { registrant: c, admin: c, tech: c, billing: c },
      privacyEnabled: true,
    },
    purchasePrice: purchaseCents / 100,
    years,
  });
  const exp = json?.domain?.expireDate ?? json?.order?.expireDate;
  return { expiresAt: exp ? new Date(exp) : undefined };
}

export async function renewDomain(domain: string, years: number, purchaseCents: number): Promise<void> {
  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:renew`, {
    purchasePrice: purchaseCents / 100,
    years,
  });
}

export async function domainInfo(domain: string): Promise<{ expires?: Date; created?: Date }> {
  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}`);
  return {
    expires: json?.expireDate ? new Date(json.expireDate) : undefined,
    created: json?.createDate ? new Date(json.createDate) : undefined,
  };
}

// ---------- Inbound transfers (transfer-in) ----------
//
// name.com v4 transfers:
//   POST /v4/transfers                      { domainName, authCode, privacyEnabled, purchasePrice }
//   GET  /v4/transfers                      -> { transfers: [...] }
//   GET  /v4/transfers/{domainName}         -> { domainName, email, status }
//   POST /v4/transfers/{domainName}:cancel  -> { domainName, email, status }
//
// A transfer always includes a 1-year extension of the registration, which is
// why it is priced off the TLD's RENEWAL rate rather than its promo/first-year
// registration rate.

/** Compressed sandbox timeline (real transfers take 5-7 days — see SANDBOX_* notes). */
const SANDBOX_APPROVAL_MS = 2 * 60_000;
const SANDBOX_REGISTRY_MS = 5 * 60_000;

/** Deterministic synthetic per-year cost for a TLD in sandbox (integer cents). */
function sandboxTldCostCents(domain: string): number {
  const tld = domain.slice(domain.lastIndexOf(".") + 1);
  let h = 0;
  for (const ch of tld) h = (h * 31 + ch.charCodeAt(0)) % 997;
  return 900 + (h % 21) * 50; // $9.00 – $19.00
}

export type TransferCheck = {
  domain: string;
  /** True when we believe an inbound transfer can be submitted for this name. */
  transferable: boolean;
  /** Plain-English reason when `transferable` is false. */
  reason: string | null;
  premium: boolean;
  /** RETAIL price the customer pays — covers the transfer + 1 extra year. */
  priceCents: number | null;
  /** Registrar cost we pay name.com (what we send as `purchasePrice`). */
  costCents: number | null;
};

/**
 * The registrar cost of transferring `domain`, in integer cents.
 *
 * Transfers are billed at the TLD's renewal rate. name.com only reliably prices
 * a name it can see, so we try three sources in order and give up honestly:
 *   1. the availability result for the domain itself,
 *   2. the per-domain pricing endpoint,
 *   3. a throwaway probe name on the same TLD — TLD pricing is per-TLD, so an
 *      unregistered sibling quotes the same renewal rate.
 */
async function transferCostCents(domain: string, availability: any): Promise<number | null> {
  const own = dollarsToCents(availability?.renewalPrice ?? availability?.purchasePrice);
  if (own !== null && own > 0) return own;

  try {
    const p = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}:getPricing`);
    const quoted = dollarsToCents(p?.transferPrice ?? p?.renewalPrice ?? p?.purchasePrice);
    if (quoted !== null && quoted > 0) return quoted;
  } catch {
    /* endpoint unavailable for this TLD/account — fall through to the probe */
  }

  const tld = domain.slice(domain.indexOf(".") + 1);
  try {
    const probe = `nxeon-price-probe-${Math.random().toString(36).slice(2, 10)}.${tld}`;
    const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: [probe] });
    const r = (json.results ?? [])[0];
    const c = dollarsToCents(r?.renewalPrice ?? r?.purchasePrice);
    if (c !== null && c > 0) return c;
  } catch {
    /* registrar unhappy — no price, caller surfaces that plainly */
  }
  return null;
}

/**
 * Can this domain be transferred in, and what would it cost? Never throws for a
 * "no" answer — a non-transferable name comes back with `transferable: false`
 * and a reason the customer can act on.
 */
export async function checkTransfer(domain: string): Promise<TransferCheck> {
  if (SANDBOX) {
    // Synthetic: everything is transferable except names containing "locked",
    // which exercise the rejected-quote path in staging.
    const cost = sandboxTldCostCents(domain);
    if (domain.includes("locked")) {
      return {
        domain,
        transferable: false,
        reason: "This domain is locked at its current registrar. Unlock it there and try again.",
        premium: false,
        priceCents: null,
        costCents: null,
      };
    }
    return {
      domain,
      transferable: true,
      reason: null,
      premium: false,
      priceCents: retailCents(cost),
      costCents: cost,
    };
  }

  const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: [domain] });
  const r = (json.results ?? [])[0];
  if (!r) {
    return {
      domain,
      transferable: false,
      reason: "We couldn't look this domain up at the registrar. Check the spelling and try again.",
      premium: false,
      priceCents: null,
      costCents: null,
    };
  }
  // Purchasable means nobody owns it — there is nothing to transfer.
  if (r.purchasable === true) {
    return {
      domain,
      transferable: false,
      reason: "This domain isn't registered anywhere yet, so there's nothing to transfer — register it instead.",
      premium: r.premium === true,
      priceCents: null,
      costCents: null,
    };
  }
  if (r.premium === true) {
    return {
      domain,
      transferable: false,
      reason: "Premium domains can't be transferred in automatically — contact support.",
      premium: true,
      priceCents: null,
      costCents: null,
    };
  }

  const cost = await transferCostCents(domain, r);
  if (cost === null) {
    return {
      domain,
      transferable: false,
      reason: "We can't get a transfer price for this TLD from the registrar right now — contact support.",
      premium: false,
      priceCents: null,
      costCents: null,
    };
  }
  return { domain, transferable: true, reason: null, premium: false, priceCents: retailCents(cost), costCents: cost };
}

export type TransferInfo = {
  domain: string;
  /** Raw registrar status, shown to the customer verbatim. */
  status: string;
  /** Where the losing registrar sent the approval email (not every TLD sends one). */
  email: string | null;
};

/**
 * Submit an inbound transfer. `purchaseCents` is the registrar COST (integer
 * cents) — the same "what we expect to pay" contract `registerDomain` uses.
 * The auth code is passed straight through and never logged.
 */
export async function createTransfer(
  domain: string,
  authCode: string,
  purchaseCents: number
): Promise<TransferInfo> {
  if (SANDBOX) {
    // Names containing "fail" reject at submit time so staging can exercise the
    // "registrar refused, customer not charged" path.
    if (domain.includes("fail")) throw new Error("name.com: transfer rejected by the registry (sandbox)");
    return { domain, status: "pendingOwnerApproval", email: `owner@${domain}` };
  }
  const json = await nc("POST", "/v4/transfers", {
    domainName: domain,
    authCode,
    privacyEnabled: true,
    purchasePrice: purchaseCents / 100,
  });
  const t = json?.transfer ?? json ?? {};
  return {
    domain: t.domainName ?? domain,
    status: String(t.status ?? "pending"),
    email: t.email ? String(t.email) : null,
  };
}

/**
 * Current state of an inbound transfer. Returns null when the registrar has no
 * transfer for this domain — which is a NORMAL answer once a transfer settles
 * and drops off the list, so callers must resolve that against `domainInfo`
 * rather than treating it as a failure.
 *
 * `startedAt` is only read in SANDBOX, where it drives a synthetic progression
 * (registrar.ts holds no state of its own).
 */
export async function getTransfer(domain: string, startedAt?: Date | null): Promise<TransferInfo | null> {
  if (SANDBOX) {
    const age = Date.now() - (startedAt?.getTime() ?? Date.now());
    const status =
      age < SANDBOX_APPROVAL_MS
        ? "pendingOwnerApproval"
        : age < SANDBOX_REGISTRY_MS
          ? "pendingRegistry"
          : "completed";
    return { domain, status, email: `owner@${domain}` };
  }
  const t = await nc("GET", `/v4/transfers/${encodeURIComponent(domain)}`, undefined, { nullOn404: true });
  if (!t) return null;
  return {
    domain: t.domainName ?? domain,
    status: String(t.status ?? "pending"),
    email: t.email ? String(t.email) : null,
  };
}

/**
 * Ask the registrar to cancel an in-flight inbound transfer. Throws if the
 * registrar refuses (e.g. the transfer already completed at the registry) —
 * callers must NOT credit the customer unless this resolves.
 */
export async function cancelTransfer(domain: string): Promise<TransferInfo> {
  if (SANDBOX) return { domain, status: "cancelled", email: null };
  const t = await nc("POST", `/v4/transfers/${encodeURIComponent(domain)}:cancel`, {});
  return {
    domain: t?.domainName ?? domain,
    status: String(t?.status ?? "cancelled"),
    email: t?.email ? String(t.email) : null,
  };
}

/** All inbound transfers on the reseller account (ops/debug — not used per-domain). */
export async function listTransfers(): Promise<TransferInfo[]> {
  if (SANDBOX) return [];
  const json = await nc("GET", "/v4/transfers");
  return (json.transfers ?? []).map((t: any) => ({
    domain: t.domainName,
    status: String(t.status ?? "pending"),
    email: t.email ? String(t.email) : null,
  }));
}

/** Bucket a raw registrar transfer status into something we can act on. */
export function transferOutcome(status: string): "completed" | "failed" | "pending" {
  const s = status.toLowerCase();
  if (/(complete|success|transferred)/.test(s)) return "completed";
  if (/(cancel|reject|denied|fail|expired|refund|void)/.test(s)) return "failed";
  return "pending";
}

/** Human label for a raw registrar transfer status. */
export function transferStatusLabel(status: string): string {
  const s = status.toLowerCase();
  if (/owner|admin|approval|contact/.test(s)) return "Waiting for you to approve the confirmation email";
  if (/registry|processing|progress/.test(s)) return "Submitted to the registry";
  if (/complete|success|transferred/.test(s)) return "Completed";
  if (/cancel/.test(s)) return "Cancelled";
  if (/reject|denied/.test(s)) return "Rejected by the losing registrar";
  if (/expired/.test(s)) return "Expired — the confirmation was never approved";
  return status;
}

// ---------- DNS ----------

export type DnsRecord = {
  id: number;
  host: string; // "" = apex
  type: string;
  answer: string;
  ttl: number;
  priority?: number;
};

export async function listRecords(domain: string): Promise<DnsRecord[]> {
  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}/records`);
  return (json.records ?? []).map((r: any) => ({
    id: r.id,
    host: r.host ?? "",
    type: r.type,
    answer: r.answer,
    ttl: r.ttl ?? 300,
    priority: r.priority,
  }));
}

export async function addRecord(
  domain: string,
  rec: { host: string; type: string; answer: string; ttl?: number; priority?: number }
): Promise<void> {
  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}/records`, {
    host: rec.host,
    type: rec.type,
    answer: rec.answer,
    ttl: rec.ttl ?? 300,
    ...(rec.priority !== undefined ? { priority: rec.priority } : {}),
  });
}

export async function deleteRecord(domain: string, id: number): Promise<void> {
  await nc("DELETE", `/v4/domains/${encodeURIComponent(domain)}/records/${id}`);
}

/** Read-only view used by the DNS UI: apex host shown as "@". */
export type DnsHost = { name: string; type: string; address: string; ttl: number; mxPref?: number };

export async function getDnsHosts(domain: string): Promise<DnsHost[]> {
  const recs = await listRecords(domain);
  return recs.map((r) => ({
    name: r.host === "" ? "@" : r.host,
    type: r.type,
    address: r.answer,
    ttl: r.ttl,
    mxPref: r.priority,
  }));
}

