/**
 * Non-AI domain-name generator — the fallback that keeps the public tool useful
 * when ANTHROPIC_API_KEY is not configured (or Claude errors/times out).
 *
 * This is deliberately NOT "<keyword> + <tld>" permutation. It runs six naming
 * strategies over a topic vocabulary (see `domain-vocab.ts`), scores every
 * candidate for length, pronounceability and keyword relevance, then keeps the
 * best spread of styles. The output is a list of bare second-level labels — the
 * caller pairs them with TLDs and checks availability.
 *
 * Pure functions, no I/O, deterministic apart from an explicitly seeded RNG so
 * two visitors with the same brief don't get an identical page.
 */

import {
  BRAND_PREFIXES,
  BRAND_SUFFIXES,
  COINED_ROOTS,
  STANDALONE_WORDS,
  TONE_WORDS,
  TOPIC_WORDS,
  type Tone,
} from "./domain-vocab";

export type NameStyle = "compound" | "invented" | "real-word" | "playful" | "descriptive";

export type Candidate = {
  /** Bare second-level label, lowercase a-z0-9 only. */
  sld: string;
  style: NameStyle;
  /** One short line on why it works. Shown as muted helper text. */
  note: string;
};

/* ---------------------------------------------------------------------------
 * Text handling
 * ------------------------------------------------------------------------ */

const STOPWORDS = new Set([
  "a", "an", "and", "are", "as", "at", "be", "but", "by", "for", "from", "get",
  "has", "have", "he", "her", "his", "how", "i", "in", "is", "it", "its", "me",
  "my", "of", "on", "or", "our", "she", "so", "that", "the", "their", "them",
  "then", "there", "these", "they", "this", "to", "us", "was", "we", "were",
  "what", "when", "where", "which", "who", "will", "with", "you", "your",
  "business", "company", "startup", "brand", "new", "want", "need", "make",
  "making", "help", "helps", "people", "customers", "clients", "online",
  "platform", "service", "services", "product", "products", "app", "website",
  "site", "team", "small", "local", "best", "great", "good", "own", "run",
  "running", "based", "using", "use", "offer", "offers", "sell", "selling",
]);

/** Lowercase alphabetic tokens, stopwords dropped, order preserved. */
export function tokenize(text: string): string[] {
  return (text || "")
    .toLowerCase()
    .replace(/[^a-z0-9\s'-]/g, " ")
    .split(/[\s'-]+/)
    .map((w) => w.replace(/[^a-z0-9]/g, ""))
    .filter((w) => w.length > 1 && !STOPWORDS.has(w));
}

/** Strip a candidate down to a legal DNS label, or null if nothing survives. */
export function normalizeSld(raw: string): string | null {
  const s = (raw || "")
    .toLowerCase()
    .trim()
    .replace(/^https?:\/\//, "")
    .replace(/\..*$/, "") // drop anything the model appended as a TLD
    .replace(/[^a-z0-9-]/g, "")
    .replace(/^-+|-+$/g, "");
  if (s.length < 3 || s.length > 30) return null;
  if (s.startsWith("xn--")) return null; // punycode — not something we coin
  if (/^\d+$/.test(s)) return null;
  return s;
}

/* ---------------------------------------------------------------------------
 * Scoring
 * ------------------------------------------------------------------------ */

const VOWELS = new Set(["a", "e", "i", "o", "u", "y"]);

/** Rough syllable count — good enough to reject unsayable strings. */
function syllables(word: string): number {
  let count = 0;
  let prevVowel = false;
  for (const ch of word) {
    const isVowel = VOWELS.has(ch);
    if (isVowel && !prevVowel) count++;
    prevVowel = isVowel;
  }
  return Math.max(1, count);
}

/** Longest run of consecutive consonants — 4+ is usually unpronounceable. */
function maxConsonantRun(word: string): number {
  let run = 0;
  let best = 0;
  for (const ch of word) {
    if (VOWELS.has(ch)) run = 0;
    else {
      run++;
      if (run > best) best = run;
    }
  }
  return best;
}

/**
 * Heuristic quality score (higher is better). Rewards short, sayable, one- or
 * two-word names that still echo the visitor's keywords; punishes hyphens,
 * digits, triple letters and consonant pile-ups.
 */
export function scoreSld(sld: string, keywords: string[]): number {
  let score = 100;

  // Length: 6-12 characters is the sweet spot for a memorable brand.
  const len = sld.length;
  if (len <= 5) score += 6;
  else if (len <= 9) score += 12;
  else if (len <= 12) score += 4;
  else if (len <= 16) score -= 10;
  else score -= 26;

  // Pronounceability.
  const syl = syllables(sld);
  if (syl <= 3) score += 8;
  else if (syl === 4) score -= 4;
  else score -= 14;

  const run = maxConsonantRun(sld);
  if (run >= 5) score -= 30;
  else if (run === 4) score -= 14;

  // Typing hazards.
  if (sld.includes("-")) score -= 22;
  if (/\d/.test(sld)) score -= 18;
  if (/(.)\1\1/.test(sld)) score -= 20; // three of the same letter
  if (/(.)\1$/.test(sld)) score -= 4; // doubled letter at a join, e.g. "brewwave"

  // Awkward seams from naive concatenation.
  if (/([bcdfgjkpqtvxz])\1/.test(sld)) score -= 8;

  // Relevance: some echo of the brief is good, a verbatim keyword dump is not.
  const hits = keywords.filter((k) => k.length > 3 && sld.includes(k)).length;
  if (hits === 1) score += 10;
  else if (hits >= 2) score -= 6;

  // At least one vowel, please.
  if (!/[aeiouy]/.test(sld)) score -= 40;

  return score;
}

/* ---------------------------------------------------------------------------
 * Seeded RNG so results vary between visitors but stay reproducible per brief
 * ------------------------------------------------------------------------ */

function makeRng(seedText: string): () => number {
  let h = 2166136261;
  for (let i = 0; i < seedText.length; i++) {
    h ^= seedText.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  let state = h >>> 0 || 1;
  return () => {
    state ^= state << 13;
    state ^= state >>> 17;
    state ^= state << 5;
    state >>>= 0;
    return state / 4294967296;
  };
}

function pick<T>(arr: T[], rng: () => number): T {
  return arr[Math.floor(rng() * arr.length) % arr.length];
}

function shuffled<T>(arr: T[], rng: () => number): T[] {
  const out = arr.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

/* ---------------------------------------------------------------------------
 * Topic vocabulary lookup
 * ------------------------------------------------------------------------ */

/** Related brand roots for a brief, drawn from the curated topic vocabulary. */
export function topicRoots(text: string): string[] {
  const haystack = (text || "").toLowerCase().replace(/[^a-z]/g, "");
  const out: string[] = [];
  for (const [topic, words] of Object.entries(TOPIC_WORDS)) {
    if (haystack.includes(topic)) out.push(...words);
  }
  // A couple of common two-word topics the substring match would miss.
  if (/realestate|realtor|property|letting|landlord/.test(haystack)) out.push(...(TOPIC_WORDS.realestate ?? []));
  if (/onlinestore|webshop|dropship/.test(haystack)) out.push(...(TOPIC_WORDS.ecommerce ?? []));
  return [...new Set(out)];
}

/** Trim a word to a blendable stem (drops a trailing vowel-cluster). */
function stem(word: string): string {
  if (word.length <= 4) return word;
  let s = word.replace(/(ing|ers|er|ies|ed|es|s|y)$/, "");
  if (s.length < 3) s = word;
  return s;
}

/** Take the leading consonant-vowel chunk of a word, for portmanteaus. */
function head(word: string, target = 4): string {
  const s = stem(word);
  if (s.length <= target) return s;
  let cut = target;
  // Prefer cutting after a vowel so the blend stays sayable.
  while (cut < s.length && !VOWELS.has(s[cut - 1])) cut++;
  return s.slice(0, Math.min(cut, target + 2));
}

/** Take the trailing chunk of a word starting at a vowel, for portmanteaus. */
function tail(word: string, target = 4): string {
  const s = stem(word);
  if (s.length <= target) return s;
  let start = s.length - target;
  while (start > 0 && !VOWELS.has(s[start])) start--;
  return s.slice(start);
}

/* ---------------------------------------------------------------------------
 * Generation
 * ------------------------------------------------------------------------ */

export type GenerateInput = {
  idea: string;
  keywords?: string;
  tone?: Tone;
  /** How many labels to return. The API caps this well below any sane limit. */
  limit: number;
};

/**
 * Build a ranked, de-duplicated list of candidate second-level labels using
 * blend / affix / synonym / real-word strategies. Never throws; returns fewer
 * than `limit` only if the banks genuinely run dry (they don't in practice).
 */
export function generateCandidates({ idea, keywords, tone = "any", limit }: GenerateInput): Candidate[] {
  const brief = `${idea} ${keywords ?? ""}`.trim();
  const rng = makeRng(`${brief}|${tone}`);

  const briefWords = tokenize(brief);
  const kw = tokenize(keywords ?? "");
  // Keyword tokens first, then the most substantial words from the description.
  const seeds = [...new Set([...kw, ...briefWords])].filter((w) => w.length >= 3).slice(0, 8);
  const roots = topicRoots(brief);

  const toneBank = tone === "any" ? [] : TONE_WORDS[tone] ?? [];
  const flavour = shuffled([...roots, ...toneBank], rng);

  // The word pool a compound's second half is drawn from.
  const secondHalf = shuffled(
    [
      ...roots,
      ...toneBank,
      ...BRAND_SUFFIXES,
      ...STANDALONE_WORDS.slice(0, 30),
    ],
    rng,
  );

  const out = new Map<string, Candidate>();
  const add = (raw: string, style: NameStyle, note: string) => {
    const sld = normalizeSld(raw);
    if (!sld) return;
    if (!out.has(sld)) out.set(sld, { sld, style, note });
  };

  const strategies: Array<() => void> = [];

  // 1. Compound — a seed or topic root plus a second word.
  strategies.push(() => {
    const firsts = shuffled([...seeds.map(stem), ...flavour.slice(0, 10)], rng).slice(0, 10);
    for (const a of firsts) {
      for (let i = 0; i < 3; i++) {
        const b = pick(secondHalf, rng);
        if (!b || b === a || a.includes(b) || b.includes(a)) continue;
        add(`${a}${b}`, "compound", "Two familiar words — easy to say and spell.");
      }
    }
  });

  // 2. Portmanteau / coined blend — halves of two words fused.
  strategies.push(() => {
    const pool = shuffled([...seeds, ...flavour.slice(0, 12), ...COINED_ROOTS], rng);
    for (let i = 0; i < pool.length - 1 && i < 18; i++) {
      const a = head(pool[i], 4);
      const b = tail(pool[i + 1], 4);
      if (!a || !b || a === b) continue;
      // Avoid a doubled letter at the seam.
      const joined = a[a.length - 1] === b[0] ? a + b.slice(1) : a + b;
      add(joined, "invented", "Coined blend — no baggage, easy to trademark.");
    }
  });

  // 3. Affix — brandable prefix or suffix on a real root.
  strategies.push(() => {
    const bases = shuffled([...seeds.map(stem), ...flavour.slice(0, 8)], rng).slice(0, 8);
    for (const base of bases) {
      if (rng() < 0.5) {
        add(`${pick(BRAND_PREFIXES, rng)}${base}`, "playful", "Verb-first — reads like an invitation.");
      } else {
        add(`${base}${pick(BRAND_SUFFIXES, rng)}`, "compound", "Root plus a product-shaped suffix.");
      }
    }
  });

  // 4. Real word — an evocative standalone, biased toward the topic vocabulary.
  strategies.push(() => {
    const pool = shuffled([...roots, ...STANDALONE_WORDS], rng).slice(0, 14);
    for (const w of pool) {
      if (w.length < 4) continue;
      add(w, "real-word", "A real word that carries meaning on its own.");
    }
  });

  // 5. Clipped invented — drop a trailing vowel or double a consonant.
  strategies.push(() => {
    const pool = shuffled([...seeds, ...roots, ...COINED_ROOTS], rng).slice(0, 12);
    for (const w of pool) {
      if (w.length < 5) continue;
      if (VOWELS.has(w[w.length - 1])) add(w.slice(0, -1), "invented", "Clipped spelling — shorter and distinctive.");
      add(`${w}r`, "invented", "Coined variant of a word you already use.");
    }
  });

  // 6. Descriptive pair — literal, for people who want to be found not admired.
  strategies.push(() => {
    if (seeds.length < 2) return;
    const s = shuffled(seeds, rng);
    for (let i = 0; i + 1 < s.length && i < 6; i++) {
      add(`${s[i]}${s[i + 1]}`, "descriptive", "Says what you do — good for search intent.");
    }
    for (const w of s.slice(0, 4)) {
      add(`${w}${pick(["hq", "co", "studio", "group", "collective"], rng)}`, "descriptive", "Literal name with a business-shaped tail.");
    }
  });

  // Descriptive tone leads with the literal strategy; invented leads with blends.
  if (tone === "descriptive") strategies.unshift(strategies.pop()!);
  if (tone === "invented") strategies.unshift(strategies.splice(1, 1)[0]);

  for (const run of strategies) run();

  const ranked = [...out.values()]
    .map((c) => ({ c, score: scoreSld(c.sld, seeds) }))
    .filter((x) => x.score > 45)
    .sort((a, b) => b.score - a.score);

  // Interleave styles so the results page isn't ten compounds in a row.
  const byStyle = new Map<NameStyle, Candidate[]>();
  for (const { c } of ranked) {
    const list = byStyle.get(c.style) ?? [];
    list.push(c);
    byStyle.set(c.style, list);
  }
  const order: NameStyle[] = tone === "descriptive"
    ? ["descriptive", "compound", "real-word", "invented", "playful"]
    : ["compound", "invented", "real-word", "descriptive", "playful"];

  const result: Candidate[] = [];
  let exhausted = false;
  while (result.length < limit && !exhausted) {
    exhausted = true;
    for (const style of order) {
      const list = byStyle.get(style);
      if (list && list.length) {
        result.push(list.shift()!);
        exhausted = false;
        if (result.length >= limit) break;
      }
    }
  }
  return result;
}

/**
 * Claude-powered name generation for the public domain-name generator.
 *
 * Why this doesn't call `askClaude` from `lib/anthropic.ts`: that helper is the
 * BYOK path for the "Build with Claude" feature and hard-codes an Opus model.
 * This is a free, unauthenticated, high-volume SEO tool, so it needs the
 * cheapest capable model instead. We reuse `platformKeyConfigured()` from that
 * module for the key check and keep the same dependency-free plain-fetch style.
 *
 * Cost posture: Haiku, a compact system prompt, a hard `max_tokens` ceiling, one
 * request per (rate-limited) visitor request, and a short timeout. If anything
 * at all goes wrong we return null and the caller falls back to the local
 * heuristic generator — visitors never see an AI error.
 */

import { platformKeyConfigured } from "@/lib/anthropic";
import { normalizeSld, type Candidate, type NameStyle } from "./domain-generate";
import type { Tone } from "./domain-vocab";

const ANTHROPIC_URL = "https://api.anthropic.com/v1/messages";

/** Cheapest capable model. Do not upgrade this without an owner cost decision. */
const MODEL = "claude-haiku-4-5-20251001";

const MAX_TOKENS = 1200;
const TIMEOUT_MS = 20_000;

/** True when the owner has set ANTHROPIC_API_KEY and the AI path can run. */
export function aiAvailable(): boolean {
  return platformKeyConfigured();
}

const SYSTEM = `You are a senior brand naming consultant. You name companies for a living.

Given a business description, invent domain-name candidates: the second-level label only (no dot, no TLD).

Hard rules:
- lowercase a-z and digits only; never hyphens, spaces, or punctuation
- 4 to 14 characters; shorter is better
- must be pronounceable out loud on the first try by an English speaker
- must be spellable after hearing it once
- no numbers substituting for words (no "4u", "2go"), no misspelled-brand cliches
- never just <keyword>+<generic suffix> for every entry; earn each name
- avoid names that read as an existing famous brand

Aim for a genuine spread of styles:
- compound: two real words fused (e.g. "northbeam", "saltmarket")
- invented: a coined word or portmanteau with no prior meaning (e.g. "verolo", "cadenza")
- real-word: a single evocative existing word used as a brand (e.g. "thistle", "keystone")
- playful: warm, human, a little unexpected (e.g. "buttermade", "gladhand")
- descriptive: literal and searchable, when that serves the business (e.g. "roastanddeliver")

Return ONLY a JSON array, no prose, no markdown fence:
[{"name":"northbeam","style":"compound","why":"Solid and structural; suits a construction brand."}]

"why" is at most 12 words and explains the naming choice, not the business.`;

type AiRow = { name?: unknown; style?: unknown; why?: unknown };

const STYLES: NameStyle[] = ["compound", "invented", "real-word", "playful", "descriptive"];

function coerceStyle(v: unknown): NameStyle {
  const s = String(v ?? "").toLowerCase().replace(/[\s_]+/g, "-");
  return (STYLES as string[]).includes(s) ? (s as NameStyle) : "invented";
}

/** Pull the first JSON array out of a model reply, tolerating stray prose/fences. */
function extractJsonArray(text: string): unknown[] | null {
  const start = text.indexOf("[");
  const end = text.lastIndexOf("]");
  if (start === -1 || end <= start) return null;
  try {
    const parsed = JSON.parse(text.slice(start, end + 1));
    return Array.isArray(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

const TONE_BRIEF: Record<Tone, string> = {
  any: "Mix every style roughly evenly.",
  modern: "Lean modern and short: clipped, punchy, one or two syllables.",
  invented: "Lean invented: coined words and portmanteaus with no prior meaning.",
  playful: "Lean playful: warm, human, a little unexpected — but still credible.",
  professional: "Lean professional: credible for finance, law, healthcare and B2B buyers.",
  descriptive: "Lean descriptive: literal names a customer would search for.",
};

/**
 * Ask Claude for `count` candidate labels. Returns null on missing key, HTTP
 * error, timeout, or unparseable output — the caller must have a fallback.
 */
export async function aiCandidates(opts: {
  idea: string;
  keywords?: string;
  tone: Tone;
  count: number;
}): Promise<Candidate[] | null> {
  const apiKey = process.env.ANTHROPIC_API_KEY?.trim();
  if (!apiKey) return null;

  const parts = [
    `Business description: ${opts.idea}`,
    opts.keywords ? `Words the owner would like worked in (optional, not mandatory): ${opts.keywords}` : "",
    TONE_BRIEF[opts.tone] ?? TONE_BRIEF.any,
    `Return exactly ${opts.count} candidates as the JSON array described above.`,
  ].filter(Boolean);

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);
  let res: Response;
  try {
    res = await fetch(ANTHROPIC_URL, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-api-key": apiKey,
        "anthropic-version": "2023-06-01",
      },
      body: JSON.stringify({
        model: MODEL,
        max_tokens: MAX_TOKENS,
        system: SYSTEM,
        messages: [{ role: "user", content: parts.join("\n\n") }],
      }),
      signal: controller.signal,
    });
  } catch {
    return null; // network error or timeout
  } finally {
    clearTimeout(timer);
  }

  if (!res.ok) return null;

  let text: string;
  try {
    const data = (await res.json()) as { content?: Array<{ type: string; text?: string }> };
    text = (data.content ?? [])
      .filter((b) => b.type === "text" && typeof b.text === "string")
      .map((b) => b.text as string)
      .join("")
      .trim();
  } catch {
    return null;
  }

  const rows = extractJsonArray(text);
  if (!rows) return null;

  const out: Candidate[] = [];
  const seen = new Set<string>();
  for (const row of rows) {
    if (!row || typeof row !== "object") continue;
    const r = row as AiRow;
    const sld = normalizeSld(String(r.name ?? ""));
    if (!sld || seen.has(sld)) continue;
    seen.add(sld);
    const why = typeof r.why === "string" ? r.why.trim().slice(0, 90) : "";
    out.push({ sld, style: coerceStyle(r.style), note: why });
    if (out.length >= opts.count) break;
  }
  return out.length ? out : null;
}

/**
 * Batched, cached, globally-throttled availability lookups for the public
 * domain-name generator.
 *
 * The registrar (name.com, via `lib/registrar.ts`) is a METERED third-party API
 * on a public unauthenticated endpoint, so three protections sit in front of it:
 *
 *   1. CACHE     — a short-TTL in-process map keyed by domain. Repeat lookups
 *                  (same visitor re-rolling, two visitors with the same brief,
 *                  popular industry pages) cost nothing.
 *   2. BATCHING  — name.com's `domains:checkAvailability` takes an array, so a
 *                  whole page of candidates is ONE upstream call. Verified at
 *                  25 names/call in ~0.9s.
 *   3. GLOBAL CAP — a process-wide sliding window on top of the per-IP limit in
 *                  the route, so a botnet spread across many IPs still cannot
 *                  push unbounded volume at the registrar.
 *
 * Prices are only ever what the registrar returned. When the API gives us no
 * price we surface no price — never an estimate, never a TLD average.
 */

import { checkRateLimit } from "@/lib/rate-limit";
import { checkDomains, registrarConfigured, type DomainCheck } from "@/lib/registrar";

/** Max domains sent in a single upstream call. Verified working at 25. */
const BATCH_SIZE = 24;

/** Cache lifetime. Long enough to absorb re-rolls, short enough to stay honest. */
const CACHE_TTL_MS = 10 * 60 * 1000;

/** Hard ceiling on entries so the map can't grow unbounded. */
const CACHE_MAX = 4000;

/** Process-wide registrar budget: batches per minute across ALL visitors. */
const GLOBAL_BATCHES_PER_MIN = 60;

type Entry = { at: number; check: DomainCheck };

const localCache = new Map<string, Entry>();
// Survive HMR / route reloads in dev so the cache actually caches.
const globalForCache = globalThis as unknown as { __nxeonDomainAvail?: Map<string, Entry> };
const cache: Map<string, Entry> = globalForCache.__nxeonDomainAvail ?? localCache;
if (process.env.NODE_ENV !== "production") globalForCache.__nxeonDomainAvail = cache;

function readCache(domain: string, now: number): DomainCheck | null {
  const hit = cache.get(domain);
  if (!hit) return null;
  if (now - hit.at > CACHE_TTL_MS) {
    cache.delete(domain);
    return null;
  }
  return hit.check;
}

function writeCache(check: DomainCheck, now: number): void {
  if (cache.size >= CACHE_MAX) {
    // Drop the oldest ~10% rather than clearing everything on a cold spike.
    const victims = [...cache.entries()]
      .sort((a, b) => a[1].at - b[1].at)
      .slice(0, Math.ceil(CACHE_MAX / 10));
    for (const [k] of victims) cache.delete(k);
  }
  cache.set(check.domain, { at: now, check });
}

export type AvailabilityStatus = "available" | "taken" | "unknown";

export type DomainResult = {
  domain: string;
  status: AvailabilityStatus;
  premium: boolean;
  /** Retail first-year price in integer cents, or null when the registrar gave none. */
  priceCents: number | null;
  /** Retail renewal price in integer cents, or null. */
  renewCents: number | null;
};

export type AvailabilityOutcome = {
  results: DomainResult[];
  /** False when the registrar isn't configured at all — everything is "unknown". */
  configured: boolean;
  /** True when we skipped the registrar to protect the shared upstream budget. */
  throttled: boolean;
  /** How many domains were served from cache rather than the registrar. */
  cached: number;
};

function toResult(check: DomainCheck): DomainResult {
  // name.com only prices a purchasable name; a taken domain comes back priceless.
  const available = check.available && check.priceCents !== null;
  return {
    domain: check.domain,
    status: available ? "available" : "taken",
    premium: check.premium,
    priceCents: available ? check.priceCents : null,
    renewCents: available ? check.renewCents : null,
  };
}

function unknown(domain: string): DomainResult {
  return { domain, status: "unknown", premium: false, priceCents: null, renewCents: null };
}

/**
 * Look up availability for a list of domains, preserving input order.
 *
 * Never throws: a registrar outage degrades every uncached domain to `unknown`
 * so the page still renders names, clearly marked as unverified.
 */
export async function checkAvailabilityBatched(domains: string[]): Promise<AvailabilityOutcome> {
  const now = Date.now();
  const unique = [...new Set(domains.map((d) => d.toLowerCase()))];

  if (!registrarConfigured()) {
    return { results: unique.map(unknown), configured: false, throttled: false, cached: 0 };
  }

  const resolved = new Map<string, DomainResult>();
  const misses: string[] = [];
  for (const d of unique) {
    const hit = readCache(d, now);
    if (hit) resolved.set(d, toResult(hit));
    else misses.push(d);
  }
  const cached = resolved.size;

  let throttled = false;
  const batches: string[][] = [];
  for (let i = 0; i < misses.length; i += BATCH_SIZE) batches.push(misses.slice(i, i + BATCH_SIZE));

  for (const batch of batches) {
    // Shared upstream budget — checked per batch, not per domain.
    const budget = checkRateLimit("registrar:availability:global", {
      max: GLOBAL_BATCHES_PER_MIN,
      windowMs: 60_000,
    });
    if (!budget.ok) {
      throttled = true;
      for (const d of batch) resolved.set(d, unknown(d));
      continue;
    }

    try {
      const checks = await checkDomains(batch);
      const seen = new Set<string>();
      for (const check of checks) {
        const key = check.domain.toLowerCase();
        seen.add(key);
        writeCache({ ...check, domain: key }, now);
        resolved.set(key, toResult(check));
      }
      // A domain the registrar simply didn't answer for stays honest.
      for (const d of batch) if (!seen.has(d)) resolved.set(d, unknown(d));
    } catch {
      for (const d of batch) resolved.set(d, unknown(d));
    }
  }

  return {
    results: unique.map((d) => resolved.get(d) ?? unknown(d)),
    configured: true,
    throttled,
    cached,
  };
}

/** `$12.99` from integer cents. Returns null so callers can't print a fake price. */
export function formatPrice(cents: number | null): string | null {
  if (cents === null || !Number.isFinite(cents)) return null;
  return `$${(cents / 100).toFixed(2)}`;
}

import { NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { jsonError, toolRateLimit } from "@/lib/tools/api";
import { aiAvailable, aiCandidates } from "@/lib/tools/domain-ai";
import { checkAvailabilityBatched, type DomainResult } from "@/lib/tools/domain-availability";
import { generateCandidates, type Candidate } from "@/lib/tools/domain-generate";
import { ALLOWED_TLDS, DEFAULT_TLDS, TONES, type Tone } from "@/lib/tools/domain-vocab";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * AI domain-name generator — public, unauthenticated, and therefore capped hard.
 *
 * Cost controls, in order of defence:
 *   1. Two per-IP sliding windows (burst + hourly) via the shared tool limiter.
 *   2. MAX_NAMES caps how many labels we generate, so at most ONE Claude call
 *      with a fixed `max_tokens` per accepted request.
 *   3. MAX_LOOKUPS caps registrar volume per request; the lookups are batched
 *      into a single upstream call and cached for 10 minutes, and a process-wide
 *      window in `domain-availability.ts` guards the shared registrar budget.
 *
 * Degradation: no ANTHROPIC_API_KEY (or any Claude failure) falls back to the
 * local heuristic generator; a registrar failure marks names "unknown" rather
 * than claiming they're free. Neither is surfaced to the visitor as an error.
 */

/** Distinct name ideas per request. */
const MAX_NAMES = 12;

/** Absolute ceiling on registrar lookups per request (names x TLDs). */
const MAX_LOOKUPS = 24;

/** TLDs a visitor may select at once. */
const MAX_TLDS = 3;

const MAX_IDEA_LEN = 400;
const MAX_KEYWORDS_LEN = 120;

const VALID_TONES = new Set(TONES.map((t) => t.value));

type Body = { idea?: unknown; keywords?: unknown; tone?: unknown; tlds?: unknown };

function readString(v: unknown, max: number): string {
  return typeof v === "string" ? v.replace(/\s+/g, " ").trim().slice(0, max) : "";
}

function readTlds(v: unknown): string[] {
  if (!Array.isArray(v)) return DEFAULT_TLDS;
  const out: string[] = [];
  for (const raw of v) {
    if (typeof raw !== "string") continue;
    const tld = raw.toLowerCase().replace(/^\./, "").trim();
    if (ALLOWED_TLDS.has(tld) && !out.includes(tld)) out.push(tld);
    if (out.length >= MAX_TLDS) break;
  }
  return out.length ? out : DEFAULT_TLDS;
}

/**
 * Pair labels with TLDs, TLD-major, capped at MAX_LOOKUPS. TLD-major means the
 * visitor's first-choice extension is checked for every name before we spend any
 * budget on the second choice.
 */
function buildDomains(candidates: Candidate[], tlds: string[]): string[] {
  const domains: string[] = [];
  for (const tld of tlds) {
    for (const c of candidates) {
      if (domains.length >= MAX_LOOKUPS) return domains;
      domains.push(`${c.sld}.${tld}`);
    }
  }
  return domains;
}

export async function POST(req: Request) {
  // Burst limit, then a longer window so a single IP can't grind all day.
  const burst = toolRateLimit(req, "domain-generator", { max: 6, windowMs: 60_000 });
  if (burst) return burst;
  const hourly = toolRateLimit(req, "domain-generator-hourly", { max: 40, windowMs: 60 * 60_000 });
  if (hourly) return hourly;

  const body = (await req.json().catch(() => ({}))) as Body;
  const idea = readString(body.idea, MAX_IDEA_LEN);
  const keywords = readString(body.keywords, MAX_KEYWORDS_LEN);
  const toneRaw = readString(body.tone, 20);
  const tone: Tone = VALID_TONES.has(toneRaw as Tone) ? (toneRaw as Tone) : "any";
  const tlds = readTlds(body.tlds);

  if (idea.length < 8) {
    return jsonError("Describe your business or idea in a few words (at least 8 characters).");
  }

  // 1) Names — Claude when the platform key is set, heuristics otherwise.
  let candidates: Candidate[] | null = null;
  let source: "ai" | "heuristic" = "heuristic";
  if (aiAvailable()) {
    candidates = await aiCandidates({ idea, keywords, tone, count: MAX_NAMES });
    if (candidates && candidates.length) source = "ai";
  }
  if (!candidates || candidates.length < MAX_NAMES) {
    const local = generateCandidates({ idea, keywords, tone, limit: MAX_NAMES });
    const merged = candidates ? [...candidates] : [];
    const seen = new Set(merged.map((c) => c.sld));
    for (const c of local) {
      if (merged.length >= MAX_NAMES) break;
      if (seen.has(c.sld)) continue;
      seen.add(c.sld);
      merged.push(c);
    }
    candidates = merged;
  }

  if (!candidates.length) {
    return jsonError("We couldn't build names from that description — try adding a little more detail.");
  }

  const byLabel = new Map(candidates.map((c) => [c.sld, c]));

  // 2) Availability — one batched, cached registrar call.
  const domains = buildDomains(candidates, tlds);
  const availability = await checkAvailabilityBatched(domains);

  const results = availability.results.map((r: DomainResult) => {
    const sld = r.domain.slice(0, r.domain.lastIndexOf("."));
    const tld = r.domain.slice(r.domain.lastIndexOf(".") + 1);
    const meta = byLabel.get(sld);
    return {
      domain: r.domain,
      sld,
      tld,
      status: r.status,
      premium: r.premium,
      priceCents: r.priceCents,
      renewCents: r.renewCents,
      style: meta?.style ?? "invented",
      note: meta?.note ?? "",
    };
  });

  // Available first (cheapest first within that), then unknown, then taken.
  const rank = { available: 0, unknown: 1, taken: 2 } as const;
  results.sort(
    (a, b) =>
      rank[a.status] - rank[b.status] ||
      (a.priceCents ?? Number.MAX_SAFE_INTEGER) - (b.priceCents ?? Number.MAX_SAFE_INTEGER) ||
      a.domain.length - b.domain.length,
  );

  // Signed-in visitors go straight into the pre-filled registration wizard;
  // everyone else lands on signup with the name carried through.
  let signedIn = false;
  try {
    signedIn = Boolean(await currentUser());
  } catch {
    /* session lookup unavailable — treat as anonymous */
  }

  return NextResponse.json({
    ok: true,
    source,
    signedIn,
    registrarConfigured: availability.configured,
    throttled: availability.throttled,
    checked: results.length,
    tlds,
    results,
  });
}

"use client";

import Link from "next/link";
import { useEffect, useRef, useState } from "react";
import { IconArrow, IconCheck } from "../icons";
import { CopyButton, ErrorNote, Field, RunButton } from "./ui";
import { DEFAULT_TLDS, SUGGESTABLE_TLDS, TONES, type Tone } from "@/lib/tools/domain-vocab";

/**
 * Interactive island for /tools/domain-name-generator.
 *
 * Honesty rules baked into the UI:
 *  - Prices are only rendered when the registrar actually returned one.
 *  - "Available" is always framed as available *right now, at the registrar*;
 *    the registration flow is the source of truth at checkout.
 *  - When the registrar can't be reached, names are marked "not checked" rather
 *    than being presented as free.
 */

type Status = "available" | "taken" | "unknown";

type Result = {
  domain: string;
  sld: string;
  tld: string;
  status: Status;
  premium: boolean;
  priceCents: number | null;
  renewCents: number | null;
  style: string;
  note: string;
};

type ApiResponse = {
  ok: true;
  source: "ai" | "heuristic";
  signedIn: boolean;
  registrarConfigured: boolean;
  throttled: boolean;
  checked: number;
  tlds: string[];
  results: Result[];
};

const MAX_TLDS = 3;
const MAX_IDEA = 400;

const STYLE_LABEL: Record<string, string> = {
  compound: "Compound",
  invented: "Invented",
  "real-word": "Real word",
  playful: "Playful",
  descriptive: "Descriptive",
};

function money(cents: number | null): string | null {
  if (cents === null) return null;
  return `$${(cents / 100).toFixed(2)}`;
}

const LOADING_STEPS = [
  "Reading your brief…",
  "Shaping name candidates…",
  "Checking live availability at the registrar…",
  "Pricing what's still free…",
];

export function DomainGeneratorTool({ presetIdea = "", presetTone }: { presetIdea?: string; presetTone?: Tone }) {
  const [idea, setIdea] = useState(presetIdea);
  const [keywords, setKeywords] = useState("");
  const [tone, setTone] = useState<Tone>(presetTone ?? "any");
  const [tlds, setTlds] = useState<string[]>(DEFAULT_TLDS);
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState(0);
  const [error, setError] = useState("");
  const [data, setData] = useState<ApiResponse | null>(null);
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);

  useEffect(() => () => timers.current.forEach(clearTimeout), []);

  function toggleTld(tld: string) {
    setTlds((prev) => {
      if (prev.includes(tld)) return prev.length === 1 ? prev : prev.filter((t) => t !== tld);
      if (prev.length >= MAX_TLDS) return prev;
      return [...prev, tld];
    });
  }

  async function run(e: React.FormEvent) {
    e.preventDefault();
    if (idea.trim().length < 8 || loading) return;
    setLoading(true);
    setError("");
    setData(null);
    setStep(0);
    timers.current.forEach(clearTimeout);
    timers.current = LOADING_STEPS.slice(1).map((_, i) =>
      setTimeout(() => setStep(i + 1), 900 * (i + 1)),
    );

    try {
      const res = await fetch("/api/tools/domain-generator", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ idea, keywords, tone, tlds }),
      });
      const json = await res.json();
      if (!res.ok || !json.ok) throw new Error(json.error || "We couldn't generate names just now.");
      setData(json as ApiResponse);
    } catch (err) {
      setError(err instanceof Error ? err.message : "We couldn't generate names just now.");
    } finally {
      timers.current.forEach(clearTimeout);
      setLoading(false);
    }
  }

  const available = data?.results.filter((r) => r.status === "available") ?? [];
  const unchecked = data?.results.filter((r) => r.status === "unknown") ?? [];
  const taken = data?.results.filter((r) => r.status === "taken") ?? [];

  const registerHref = (domain: string) =>
    data?.signedIn
      ? `/dashboard/domains/register?domain=${encodeURIComponent(domain)}`
      : `/register?domain=${encodeURIComponent(domain)}`;

  return (
    <div className="space-y-6">
      <style>{`
        .nx-name-row { animation: nx-name-in .32s cubic-bezier(.22,1,.36,1) both; }
        @keyframes nx-name-in { from { opacity:0; transform: translateY(6px);} to { opacity:1; transform:none;} }
        .nx-skel { animation: nx-skel 1.2s ease-in-out infinite; }
        @keyframes nx-skel { 0%,100%{opacity:.35} 50%{opacity:.7} }
        @media (prefers-reduced-motion: reduce) { .nx-name-row, .nx-skel { animation: none !important; } }
      `}</style>

      <form onSubmit={run} className="space-y-5">
        <Field
          label="What are you building?"
          hint="A sentence or two is plenty. The more specific, the better the names."
