                >
                  {t.label}
                </button>
              );
            })}
          </div>
          <p className="mt-2 text-xs text-slate-500">
            We check your first extension across every name before spending checks on the next one.
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <RunButton loading={loading} type="submit" disabled={idea.trim().length < 8}>
            Generate names
