          <span className="text-xs text-slate-500">Free, no account needed. Live availability from our registrar.</span>
        </div>
      </form>

      <ErrorNote>{error}</ErrorNote>

      {loading && (
        <div className="rounded-xl border border-white/[0.07] bg-navy-950/50 p-4">
          <p className="flex items-center gap-2 text-sm text-slate-300">
            <span className="nx-skel h-2 w-2 rounded-full bg-brand-400" />
            {LOADING_STEPS[Math.min(step, LOADING_STEPS.length - 1)]}
          </p>
          <div className="mt-4 space-y-2">
            {Array.from({ length: 5 }).map((_, i) => (
              <div
                key={i}
                className="nx-skel h-11 rounded-xl border border-white/[0.05] bg-white/[0.03]"
                style={{ animationDelay: `${i * 120}ms` }}
              />
            ))}
          </div>
        </div>
      )}

      {data && !loading && (
        <div className="space-y-6">
          {!data.registrarConfigured && (
            <div className="rounded-xl border border-amber-400/25 bg-amber-400/[0.06] px-4 py-3 text-sm text-amber-200/90">
              <b>Live availability is temporarily unavailable.</b> These are still real name ideas — check each one
              before you commit.
            </div>
          )}
          {data.registrarConfigured && data.throttled && (
            <div className="rounded-xl border border-amber-400/25 bg-amber-400/[0.06] px-4 py-3 text-sm text-amber-200/90">
              We're checking a lot of names right now, so some below weren't verified. Try again in a minute for the
              rest.
            </div>
          )}

          {available.length > 0 && (
            <section>
              <div className="mb-3 flex flex-wrap items-baseline justify-between gap-2">
                <h3 className="text-base font-semibold text-white">
                  Available right now{" "}
                  <span className="text-sm font-normal text-slate-500">({available.length})</span>
                </h3>
                <p className="text-xs text-slate-500">Price shown is the first year, from our registrar.</p>
              </div>
              <ul className="space-y-2">
                {available.map((r, i) => (
                  <li
                    key={r.domain}
                    className="nx-name-row rounded-xl border border-emerald-500/20 bg-emerald-500/[0.04] p-3 transition-colors hover:border-emerald-400/40 sm:p-4"
                    style={{ animationDelay: `${Math.min(i, 8) * 40}ms` }}
                  >
                    <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
                      <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
                        <IconCheck size={13} />
                      </span>
                      <span className="min-w-0 break-all font-mono text-[15px] font-semibold text-white">
                        {r.domain}
                      </span>
                      {r.premium && (
                        <span className="rounded-full border border-amber-400/30 bg-amber-400/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-amber-300">
                          Premium
                        </span>
                      )}
                      <span className="rounded-full border border-white/10 bg-white/[0.04] px-2 py-0.5 text-[10px] font-medium uppercase tracking-wide text-slate-400">
                        {STYLE_LABEL[r.style] ?? r.style}
                      </span>

                      <span className="ml-auto flex flex-wrap items-center gap-2 sm:gap-3">
                        {money(r.priceCents) && (
                          <span className="text-right text-sm">
                            <span className="font-semibold text-white">{money(r.priceCents)}</span>
                            <span className="text-slate-500">/yr</span>
                          </span>
                        )}
                        <CopyButton value={r.domain} label="Copy" />
                        <Link href={registerHref(r.domain)} className="btn-primary px-3.5 py-1.5 text-xs">
                          Register
                          <IconArrow size={13} />
                        </Link>
                      </span>
                    </div>
                    {(r.note || money(r.renewCents)) && (
                      <p className="mt-2 pl-9 text-xs leading-relaxed text-slate-500">
                        {r.note}
                        {r.note && money(r.renewCents) ? " · " : ""}
                        {money(r.renewCents) ? `Renews at ${money(r.renewCents)}/yr` : ""}
                      </p>
                    )}
                  </li>
                ))}
              </ul>
              <p className="mt-3 text-xs leading-relaxed text-slate-500">
                Availability comes straight from our registrar and can change minute to minute — someone else may
                register a name while you're deciding. Your registration checkout re-checks the name and its exact price
                before you pay.
              </p>
            </section>
          )}

          {available.length === 0 && (
            <div className="rounded-xl border border-white/[0.07] bg-navy-900/60 px-4 py-3 text-sm text-slate-300">
              Every name we tried is already taken. That usually means the words are too obvious — try a more specific
              description, switch the style to <b>Invented &amp; brandable</b>, or add <span className="font-mono">.io</span>{" "}
              or <span className="font-mono">.co</span> to the extensions.
            </div>
          )}

          {unchecked.length > 0 && (
            <section>
              <h3 className="mb-3 text-base font-semibold text-white">
                Not checked <span className="text-sm font-normal text-slate-500">({unchecked.length})</span>
              </h3>
              <ul className="flex flex-wrap gap-2">
                {unchecked.map((r) => (
                  <li
                    key={r.domain}
                    className="rounded-lg border border-white/[0.07] bg-navy-900/50 px-3 py-1.5 font-mono text-sm text-slate-300"
                  >
                    {r.domain}
                  </li>
                ))}
              </ul>
              <p className="mt-2 text-xs text-slate-500">
                We couldn't get an answer from the registrar for these. They may or may not be free.
              </p>
            </section>
          )}

          {taken.length > 0 && (
            <section>
              <h3 className="mb-3 text-base font-semibold text-slate-400">
                Already taken <span className="text-sm font-normal text-slate-600">({taken.length})</span>
              </h3>
              <ul className="flex flex-wrap gap-2">
                {taken.map((r) => (
                  <li
                    key={r.domain}
                    className="rounded-lg border border-white/[0.05] bg-white/[0.02] px-3 py-1.5 font-mono text-sm text-slate-600 line-through decoration-slate-700"
                  >
                    {r.domain}
                  </li>
                ))}
              </ul>
              <p className="mt-2 text-xs text-slate-600">
                Taken names sometimes free up.{" "}
                <Link href="/tools/whois" className="text-brand-400 hover:text-brand-300">
                  Run a WHOIS lookup
                </Link>{" "}
                to see when one expires.
              </p>
            </section>
          )}

          <div className="flex flex-wrap items-center gap-3 border-t border-white/[0.06] pt-4">
            <RunButton loading={false} type="button" onClick={run as unknown as () => void}>
              Generate another set
            </RunButton>
            <Link href="/domains" className="btn-secondary px-4 py-2 text-sm">
              Search an exact name
            </Link>
          </div>
        </div>
      )}
    </div>
  );
}

