/**
 * Industry variants of the domain-name generator.
 *
 * These are NOT keyword-swapped doorway pages. Each entry carries hand-written,
 * industry-specific guidance — the naming conventions that actually hold in that
 * market, the extensions buyers there expect, worked naming patterns, the
 * mistakes that market makes, and FAQs that only make sense for it. If a variant
 * can't be given genuinely different advice, it doesn't belong in this list.
 *
 * Data-only (plain strings, no JSX) so the sitemap and `generateStaticParams`
 * can import it without pulling in client code.
 */

export type NamePattern = { pattern: string; examples: string; why: string };
export type TldAdvice = { tld: string; why: string };
export type Faq = { q: string; a: string };

export type IndustryPage = {
  slug: string;
  /** Short label used in nav, breadcrumbs and cross-links. */
  label: string;
  /** <h1> on the page. */
  heading: string;
  /** <title> — written for the SERP, not for the page. */
  title: string;
  metaDescription: string;
  /** One-line pitch under the h1. */
  sub: string;
  /** Opening prose. Each string is a paragraph. */
  intro: string[];
  /** "How <industry> names actually work" — the substantive section. */
  conventions: { heading: string; paragraphs: string[] };
  patterns: NamePattern[];
  tlds: TldAdvice[];
  pitfalls: string[];
  faq: Faq[];
  /** Pre-fills the tool so the page is useful on first paint. */
  presetIdea: string;
};

export const INDUSTRY_PAGES: IndustryPage[] = [
  {
    slug: "startup",
