        a: "No. It caps your brand to one location and competes for local search terms against directories and aggregators you won't outrank. Local visibility comes from a Google Business Profile, real reviews, and location pages on your site. A neighbourhood or street reference in the name is different — that's character, not keyword stuffing.",
      },
    ],
    presetIdea: "A small strength and conditioning gym for beginners and returning lifters in Bristol",
  },
];

export const INDUSTRY_SLUGS = INDUSTRY_PAGES.map((p) => p.slug);

export function findIndustry(slug: string): IndustryPage | undefined {
  return INDUSTRY_PAGES.find((p) => p.slug === slug);
}

/** Sibling links for internal linking between industry variants. */
export function relatedIndustries(slug: string, limit = 5): { label: string; href: string }[] {
  return INDUSTRY_PAGES.filter((p) => p.slug !== slug)
    .slice(0, limit)
    .map((p) => ({ label: p.label, href: `/tools/domain-name-generator/${p.slug}` }));
}
